import{_ as t,o as s,c as o,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Disaster Recovery User Story","description":"","frontmatter":{"title":"Disaster Recovery User Story","date":"2025-06-24T00:00:00.000Z","updated":"2025-06-24T00:00:00.000Z","tags":["Ceph","存储恢复","数据一致性","系统故障","备份策略"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Disaster_Recovery_User_Story.md","filePath":"posts/2025/Disaster_Recovery_User_Story.md","lastUpdated":1780459816000}'),l={name:"posts/2025/Disaster_Recovery_User_Story.md"};function i(n,e,p,a,_,c){return s(),o("div",null,[...e[0]||(e[0]=[r("<p>本次会议主要讨论了英国MRC分子生物学实验室（LMB）在CephFS存储系统中遭遇的严重故障及其恢复过程。以下是会议的关键细节和主要议题：</p><p><strong>关键议题与讨论内容</strong></p><ol><li><p><strong>背景与系统架构</strong>：LMB使用CephFS作为主要存储方案，备份集群（Pebbles）由36个节点组成，包括17PB数据，采用SAS硬盘和NVMe存储，并使用Erasure Coding和Replication。</p></li><li><p><strong>故障现象</strong>：MDS卡在<code>laggy replay</code>状态，日志分析显示Journal损坏，可能与异步写入和RADOS Clone操作有关。</p></li><li><p><strong>恢复方案对比</strong>：</p><ul><li><strong>完整恢复</strong>：通过备份Journal、恢复元数据、重建文件系统、验证与上线等步骤进行。</li><li><strong>快速恢复</strong>：仅重置Session Map和运行<code>scan-links</code>，适用于假设元数据池未损坏的情况。</li></ul></li><li><p><strong>后续改进</strong>：调整配置、禁用异步写入、升级Ceph Squid、优化备份策略等。</p></li></ol><p><strong>决策与行动计划</strong></p><ul><li>短期行动：禁用异步写入、验证备份Journal完整性。</li><li>长期计划：迁移至Ceph Squid、测试稳定性、编写自动化恢复脚本。</li><li>风险提示：快速恢复方案需谨慎评估元数据池的健康状态。</li></ul><p><strong>遗留问题与后续讨论</strong></p><ul><li>是否需要在其他场景中调整恢复流程？</li><li>如何进一步优化<code>scan-extents</code>和<code>scan-inodes</code>的并行效率？</li></ul><p>会议强调了CephFS在处理大规模数据存储和备份时的挑战，以及如何通过有效的故障恢复策略和数据管理来保证数据的完整性和可用性。</p><p>结束了</p><p><strong>标签</strong>：</p><ul><li>Ceph</li><li>存储恢复</li><li>数据一致性</li><li>系统故障</li><li>备份策略</li></ul>",11)])])}const u=t(l,[["render",i]]);export{g as __pageData,u as default};
